{"file_path":"src/errors.js","content":"/**
 * Error types raised while parsing or scheduling a build graph. Each carries
 * enough information for the CLI to format the message the specification
 * requires and to pick the right exit code.
 */

/** The command-line arguments did not match one of the three accepted forms. */
export class UsageError extends Error {}

/** A line of input was malformed in a way tied to a specific line number. */
export class LineError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/** A `dep` line referenced a name no `task` line ever declared. */
export class UnknownTaskError extends Error {
  constructor(name) {
    super(`unknown task ${name}`)
    this.taskName = name
  }
}

/** The dependency graph contains a cycle. */
export class CycleError extends Error {
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.names = names
  }
}
"}

