{"file_path":"src/parse.js","content":"/**
 * Parses the build-graph description read from standard input into a task
 * map and a dependency adjacency map, enforcing every per-line and
 * whole-file rule the specification lists.
 */

import { LineError, UnknownTaskError } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

/**
 * Splits raw input into trimmed, non-empty, non-comment lines paired with
 * their 1-based line numbers and whitespace-split words.
 */
function tokenizeLines(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }
  const entries = []
  rawLines.forEach((raw, index) => {
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    entries.push({ line: index + 1, words: trimmed.split(/\s+/) })
  })
  return entries
}

function checkName(name, line) {
  if (!NAME_PATTERN.test(name)) {
    throw new LineError(line, `invalid task name ${name}`)
  }
}

/**
 * Parses the whole input, returning `{ names, cost, adj }` where `names` is
 * the sorted list of declared task names, `cost` maps a name to its integer
 * cost, and `adj` maps a name to the set of names it depends on.
 */
export function parseGraph(input) {
  const entries = tokenizeLines(input)

  const cost = new Map()
  const declaredAt = new Map()
  const adj = new Map()
  const depReferences = []

  for (const { line, words } of entries) {
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new LineError(line, 'expected task <name> <cost>')
      }
      const [, name, costWord] = words
      checkName(name, line)
      if (!COST_PATTERN.test(costWord)) {
        throw new LineError(line, 'cost must be a non-negative integer')
      }
      if (declaredAt.has(name)) {
        throw new LineError(line, `task ${name} is declared twice`)
      }
      declaredAt.set(name, line)
      cost.set(name, parseInt(costWord, 10))
      if (!adj.has(name)) adj.set(name, new Set())
      continue
    }

    if (directive === 'dep') {
      if (words.length < 3) {
        throw new LineError(line, 'expected dep <name> <dependency>...')
      }
      const [, from, ...deps] = words
      checkName(from, line)
      for (const dep of deps) checkName(dep, line)
      depReferences.push({ from, deps })
      continue
    }

    throw new LineError(line, `unknown directive ${directive}`)
  }

  for (const { from, deps } of depReferences) {
    if (!cost.has(from)) throw new UnknownTaskError(from)
    for (const dep of deps) {
      if (!cost.has(dep)) throw new UnknownTaskError(dep)
    }
    const set = adj.get(from)
    for (const dep of deps) set.add(dep)
  }

  const names = [...cost.keys()].sort()
  return { names, cost, adj }
}
"}

