{"file_path":"src/graph.js","content":"/**
 * Graph analysis shared by the `waves`, `explain` and `pack` modes: cycle
 * detection, dependency timings/depths, and the downstream-chain priority
 * used to break scheduling ties.
 */

import { CycleError } from './errors.js'

/**
 * Depth-first search for a cycle, starting from each task in ascending name
 * order and walking each task's dependencies in ascending name order, as the
 * specification requires. Throws a `CycleError` for the first cycle found.
 */
export function findCycle(names, adj) {
  const UNVISITED = 0
  const IN_STACK = 1
  const DONE = 2
  const state = new Map(names.map((name) => [name, UNVISITED]))
  const stack = []

  function visit(start) {
    const frame = [{ node: start, deps: null, index: 0 }]
    state.set(start, IN_STACK)
    stack.push(start)

    while (frame.length > 0) {
      const top = frame[frame.length - 1]
      if (top.deps === null) {
        top.deps = [...(adj.get(top.node) || [])].sort()
      }
      if (top.index >= top.deps.length) {
        state.set(top.node, DONE)
        stack.pop()
        frame.pop()
        continue
      }
      const dep = top.deps[top.index]
      top.index += 1
      const depState = state.get(dep)
      if (depState === IN_STACK) {
        const cycleStart = stack.indexOf(dep)
        throw new CycleError([...stack.slice(cycleStart), dep])
      }
      if (depState === UNVISITED) {
        state.set(dep, IN_STACK)
        stack.push(dep)
        frame.push({ node: dep, deps: null, index: 0 })
      }
    }
  }

  for (const name of names) {
    if (state.get(name) === UNVISITED) visit(name)
  }
}

/** Builds the reverse of `adj`: a map from a name to the names that depend on it. */
export function buildDependents(names, adj) {
  const dependents = new Map(names.map((name) => [name, []]))
  for (const [from, deps] of adj) {
    for (const dep of deps) dependents.get(dep).push(from)
  }
  return dependents
}

/**
 * Returns an order over `names` such that, for every name, everything listed
 * for it in `prereqs` appears earlier in the order. Assumes no cycle exists.
 */
function topoOrder(names, prereqs) {
  const remaining = new Map(names.map((name) => [name, (prereqs.get(name) || []).length]))
  const unlocks = new Map(names.map((name) => [name, []]))
  for (const name of names) {
    for (const prereq of prereqs.get(name) || []) unlocks.get(prereq).push(name)
  }
  const queue = names.filter((name) => remaining.get(name) === 0)
  const order = []
  while (queue.length > 0) {
    const name = queue.shift()
    order.push(name)
    for (const next of unlocks.get(name)) {
      const left = remaining.get(next) - 1
      remaining.set(next, left)
      if (left === 0) queue.push(next)
    }
  }
  return order
}

/**
 * Computes each task's start time, finish time and wave depth, along with
 * the overall makespan (0 when there are no tasks).
 */
export function computeTimings(names, adj, cost) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  let total = 0

  for (const name of topoOrder(names, adj)) {
    let s = 0
    let d = 0
    for (const dep of adj.get(name) || []) {
      if (finish.get(dep) > s) s = finish.get(dep)
      if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
    }
    const f = s + cost.get(name)
    start.set(name, s)
    finish.set(name, f)
    depth.set(name, d)
    if (f > total) total = f
  }

  return { start, finish, depth, total }
}

/**
 * Computes each task's priority: the cost of the longest chain that begins
 * at it and runs forward through its dependents.
 */
export function computePriority(names, dependents, cost) {
  const priority = new Map()
  for (const name of topoOrder(names, dependents)) {
    let best = 0
    for (const dependent of dependents.get(name) || []) {
      if (priority.get(dependent) > best) best = priority.get(dependent)
    }
    priority.set(name, cost.get(name) + best)
  }
  return priority
}
"}

