{"file_path":"src/pack.js","content":"/**
 * Simulates the build graph running on a fixed number of workers, always
 * starting the ready task with the greatest priority (ties broken by
 * ascending name) on the free worker with the smallest index.
 */

export function pack(names, adj, cost, dependents, priority, workerCount) {
  const remainingDeps = new Map(names.map((name) => [name, (adj.get(name) || []).size]))
  const ready = new Set(names.filter((name) => remainingDeps.get(name) === 0))
  const finish = new Map()
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, runs: [] }))
  let scheduledCount = 0

  function pickReady() {
    let best = null
    for (const name of ready) {
      if (
        best === null ||
        priority.get(name) > priority.get(best) ||
        (priority.get(name) === priority.get(best) && name < best)
      ) {
        best = name
      }
    }
    return best
  }

  function freeWorkerAt(time) {
    let best = -1
    for (let i = 0; i < workers.length; i += 1) {
      if (workers[i].freeAt <= time) {
        best = i
        break
      }
    }
    return best
  }

  let currentTime = 0
  while (scheduledCount < names.length) {
    let progressed = true
    while (progressed) {
      progressed = false
      const workerIndex = freeWorkerAt(currentTime)
      if (workerIndex === -1) break
      const taskName = pickReady()
      if (taskName === null) break

      ready.delete(taskName)
      const start = currentTime
      const end = start + cost.get(taskName)
      workers[workerIndex].freeAt = end
      workers[workerIndex].runs.push({ name: taskName, start, finish: end })
      finish.set(taskName, end)
      scheduledCount += 1

      for (const dependent of dependents.get(taskName) || []) {
        const left = remainingDeps.get(dependent) - 1
        remainingDeps.set(dependent, left)
        if (left === 0) ready.add(dependent)
      }

      progressed = true
    }

    if (scheduledCount >= names.length) break

    let nextTime = Infinity
    for (const worker of workers) {
      if (worker.freeAt > currentTime && worker.freeAt < nextTime) nextTime = worker.freeAt
    }
    currentTime = nextTime
  }

  const makespan = workers.reduce((max, w) => Math.max(max, w.freeAt), 0)
  return { workers, makespan }
}
"}

