{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { parseGraph } from './parse.js'
import { findCycle, buildDependents, computeTimings, computePriority } from './graph.js'
import { pack } from './pack.js'
import { UsageError, LineError, UnknownTaskError, CycleError } from './errors.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_PATTERN = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) {
      throw new Error('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new UsageError(USAGE)
}

function formatWaves(names, depth, total) {
  const waves = []
  for (const name of names) {
    const d = depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }
  const lines = []
  for (let k = 0; k < waves.length; k += 1) {
    const bucket = waves[k] || []
    bucket.sort()
    lines.push(`wave ${k}: ${bucket.join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(names, start, finish, depth, total) {
  const lines = names.map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(workers, makespan) {
  const lines = workers.map((worker, i) => {
    const runs = worker.runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    return `worker ${i}:${runs}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  let args
  try {
    args = parseArgs(process.argv.slice(2))
  } catch (error) {
    if (error instanceof UsageError) {
      process.stderr.write(`error: ${error.message}\n`)
    } else {
      process.stderr.write(`error: ${error.message}\n`)
    }
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')

  let graph
  try {
    graph = parseGraph(input)
  } catch (error) {
    if (error instanceof LineError) {
      process.stderr.write(`error: line ${error.line}: ${error.message}\n`)
    } else if (error instanceof UnknownTaskError) {
      process.stderr.write(`error: ${error.message}\n`)
    } else {
      throw error
    }
    process.exit(2)
  }

  const { names, cost, adj } = graph

  try {
    findCycle(names, adj)
  } catch (error) {
    if (error instanceof CycleError) {
      process.stderr.write(`error: ${error.message}\n`)
      process.exit(3)
    }
    throw error
  }

  const { start, finish, depth, total } = computeTimings(names, adj, cost)

  if (args.mode === 'waves') {
    process.stdout.write(formatWaves(names, depth, total))
    return
  }

  if (args.mode === 'explain') {
    process.stdout.write(formatExplain(names, start, finish, depth, total))
    return
  }

  const dependents = buildDependents(names, adj)
  const priority = computePriority(names, dependents, cost)
  const { workers, makespan } = pack(names, adj, cost, dependents, priority, args.workers)
  process.stdout.write(formatPack(workers, makespan))
}

main()
"}

